INSERT INTO cases VALUES(1,'TX-23-00042','160th District Court','GINSBERG, CARL','2023-01-13','CLOSED','TAX DELINQUENCY','WILLIAMS, RUBY J.','["WILLIAMS, RUBY J.", "WILLIAMS, GERRE GANELL", "MOTLEY, CORA PEARL", "GLORIA RUTH WILLIAMS A/K/A GLORIA AYERS HEMPHILL", "WILLIAMS, WILLIE A", "WILLIAMS, DORIS FERN", "WILLIAMS, BILLY CARL", "VELEVIA WILLIAMS JONES A/K/A VELVIA WILLIAMS JONES", "BROWN, THERESA B", "MOTLEY, JAMES"]','','','','LGBS (Linebarger)','ATKINS, ASHLY STEELE',NULL,NULL,'[]',10,1,0,'[]',1,1,1,'Citation by posting required for RUBY J. WILLIAMS, CORA PEARL MOTLEY, and BILLY CARL WILLIAMS. Attorney ad litem appointed for unknown heirs.','high','Estate/heir situation with 10 defendants including deceased owner RUBY J. WILLIAMS and multiple family members/heirs. Attorney ad litem appointed multiple times. Citation by posting required for several defendants. Multiple service difficulties.','2026-02-16','JUDGMENT NON-JURY',NULL,0,NULL,NULL,NULL,NULL,'dallas','/Users/stephenlewis/Downloads/pcpeak_platform/data/pdfs/TX-23-00042/petition.pdf','[{"entity": "Dallas County", "taxAmt": 0, "penaltyInterest": 0, "total": 0}, {"entity": "Dallas ISD", "taxAmt": 0, "penaltyInterest": 0, "total": 0}, {"entity": "City of Dallas", "taxAmt": 0, "penaltyInterest": 0, "total": 0}, {"entity": "Parkland Hospital District", "taxAmt": 0, "penaltyInterest": 0, "total": 0}, {"entity": "Dallas College", "taxAmt": 0, "penaltyInterest": 0, "total": 0}, {"entity": "Dallas County School Equalization Fund", "taxAmt": 0, "penaltyInterest": 0, "total": 0}]',replace('# ACQUISITION INTELLIGENCE MEMO\n**Case TX-23-00042 | Williams Estate, Dallas County**\n\n## PROPERTY & OWNER SITUATION\nThis is a multi-heir estate case with original owner Ruby J. Williams (deceased) and 9 additional heirs/family members named as defendants. The case was filed January 2023 and reached judgment in February 2026—a 37-month timeline. **Critical gap: all financial data is missing ($0 shown for tax debt, no property address, no assessed value).** Without debt figures or property details, we cannot calculate equity position or LTV. The 10-defendant structure and attorney ad litem appointment for unknown heirs indicates a fractured ownership with likely title complications. Citation by posting was required for three parties including the deceased original owner, signaling poor contact/awareness among heirs. This is a classic "heirs property" scenario where no one has taken responsibility for the tax burden.\n\n## TIMELINE & URGENCY\n**Case is CLOSED with judgment entered February 16, 2026.** Using the TX-23-00042 benchmark (89 days judgment-to-OOS), we should expect Order of Sale between **May 16-17, 2026**, with courthouse steps auction approximately 30 days later in **mid-June 2026**. The family has likely **60-75 days maximum** before this property hits the auction block. This matches the "HIGH complexity" timeline pattern. The urgency level is **CRITICAL** because judgment is already entered and the redemption window is rapidly closing. Any owner contact must happen within the next 2-3 weeks to allow time for negotiation and closing.\n\n## ACQUISITION STRATEGY\n**DO NOT PURSUE until financial data is obtained.** Before any owner contact, PC Peak must pull the Dallas County property records to identify: (1) actual property address and account number, (2) total tax debt with penalties/interest, (3) current assessed value, and (4) whether property is occupied. **Red flags are severe:** 10 defendants create fractured decision-making; estate/probate status may cloud title; citation by posting suggests heirs are unaware or disengaged. **IF** records show meaningful equity (property worth $150K+ with sub-$30K debt), approach the most recent occupant or "family spokesperson" via door knock first, then follow with written offer. Strategy: offer 50-60% of ARV minus full debt payoff—this gives heirs cash-out while avoiding auction. If debt exceeds 40% of value, this becomes a debt-buyout play at 110-120% of tax lien only. Without financials, this is a **HOLD/INVESTIGATE** status.','\n',char(10)),'More complex than TX-26-00009 (Rogers) due to estate situation with 10 defendants vs 1, and heir complications requiring attorney ad litem appointment.','judgment_entered',NULL,NULL,NULL,NULL,'2026-06-12T14:33:24.445325','2026-07-05T22:35:40.178233','2026-06-12T23:53:12.192787',1,NULL,NULL,NULL,NULL);
