INSERT INTO cases VALUES(3,'TX-25-01777','134th District Court','GINSBERG, CARL','2025-10-28','OPEN','TAX DELINQUENCY','STEWART, BENNY J.','["STEWART, BENNY J."]','','','','LGBS (Linebarger)','ZOKAIE, CHEYENNE MATHEW',NULL,NULL,'[]',1,0,0,'[]',0,0,0,'','low','Single defendant, service executed successfully, no estate or heir issues, standard LGBS tax foreclosure proceeding',NULL,'none',NULL,0,'2026-07-20',NULL,NULL,NULL,'dallas','/Users/stephenlewis/Downloads/pcpeak_platform/data/pdfs/TX-25-01777/petition.pdf','[{"entity": "Dallas County", "taxAmt": 0, "penaltyInterest": 0, "total": 0}, {"entity": "Dallas ISD", "taxAmt": 0, "penaltyInterest": 0, "total": 0}, {"entity": "City of Dallas", "taxAmt": 0, "penaltyInterest": 0, "total": 0}, {"entity": "Parkland Hospital District", "taxAmt": 0, "penaltyInterest": 0, "total": 0}, {"entity": "Dallas College", "taxAmt": 0, "penaltyInterest": 0, "total": 0}]',replace('# ACQUISITION INTELLIGENCE MEMO\n**Case TX-25-01777 | STEWART, BENNY J. | Dallas County**\n\n## PROPERTY & OWNER SITUATION\nOwner Benny J. Stewart faces tax foreclosure in Dallas County, though critical financial data is missing from the court record—no debt amount, delinquency years, or property address are documented. This is unusual for an LGBS filing and suggests either a newly-filed case where amended petitions are pending, or record incompleteness. The property is located in Dallas city limits, meaning combined tax entities (County, Dallas ISD, City, Parkland Hospital, Dallas College) typically result in effective rates around 2.5%. Without the property address, we cannot estimate FMV, but if we assume a modest Dallas residential property ($150K-$200K range), annual taxes would be $3,750-$5,000, meaning even 3 years delinquent would only be $15K-$20K with penalties. **RED FLAG: Missing financial data makes this impossible to underwrite properly.**\n\n## TIMELINE & URGENCY\nFiled October 28, 2025, with trial notice set for July 20, 2026—that''s an 8.6-month runway to judgment, tracking closer to the fast TX-25-00492 benchmark (14mo→J) than the slow TX-23-00042 (37mo). Service was executed successfully by November 5, 2025, and the case shows "low complexity" with no continuances, estate issues, or service problems. Based on the LOW benchmark, judgment could come as early as **December 2026** (14 months from filing), with Order of Sale potentially **90-120 days later** (March-April 2027). However, Judge Ginsberg''s docket pace is unknown. **Owner has approximately 12-16 months before losing the property.** This is early-stage but the clock is running.\n\n## ACQUISITION STRATEGY\n**DO NOT CONTACT YET.** Without debt figures, property address, or FMV data, any outreach is premature and unprofessional—we''d have no credible offer framework. **Immediate action required:** Pull Dallas CAD records using defendant name "STEWART, BENNY J." to identify the property, get current assessed value, and obtain delinquency amounts directly from the tax office. Once we have data, assuming $15K-$25K in debt on a $175K property (86-93% equity position), an acquisition range of **$120K-$145K cash** (68-83% FMV) could work—covers all taxes, gives Stewart $95K-$120K net equity, and leaves PC Peak $30K-$55K upside. If Stewart has equity awareness, **direct mail followed by door knock** is appropriate given the 12+ month timeline; no need to rush with phone pressure. If debt exceeds 40% of FMV, walk away—indicates deeper financial distress or property condition issues.','\n',char(10)),'Standard Dallas County tax foreclosure case with typical LGBS representation and successful service','pre_judgment',NULL,NULL,NULL,NULL,'2026-06-12T14:33:24.445325','2026-07-05T22:35:40.184717','2026-06-12T21:44:49.609097',1,NULL,NULL,NULL,NULL);
INSERT INTO cases VALUES(4,'TX-23-00569','','',NULL,'OPEN','TAX DELINQUENCY','','[]','','','','LGBS (Linebarger)','',NULL,NULL,'[]',1,0,0,'[]',0,0,0,'','low','Insufficient data in docket text to determine complexity - appears to be loading page only',NULL,'none',NULL,0,NULL,NULL,NULL,NULL,'dallas','/Users/stephenlewis/Downloads/pcpeak_platform/data/pdfs/TX-23-00569/petition.pdf','[]',replace('# ACQUISITION INTELLIGENCE MEMO\n**Case TX-23-00569 | Dallas County**\n\n## 1. PROPERTY & OWNER SITUATION\n**INSUFFICIENT DATA FOR ANALYSIS.** This record contains no actionable information—no defendant name, property address, account number, tax debt amount, delinquency years, or assessed value. The docket appears to be a loading page or scrape error rather than actual case data. Without knowing who owns the property, what they owe, or even the exact property location beyond "Dallas," we cannot assess equity position, debt-to-value ratio, or owner distress level. The only confirmed data points are: Dallas location, filed 2023, LGBS as counsel, and "open" status. **This case cannot be evaluated for acquisition without complete data.**\n\n## 2. TIMELINE & URGENCY\nUnknown timeline to judgment or Order of Sale. The case number suffix "-00569" suggests a 2023 filing, which would put us approximately 24 months into the tax suit cycle as of early 2025. Using benchmark TX-25-00492 (low complexity, 14 months to judgment) as a baseline for simple cases, this property may have already reached judgment. Using TX-23-00042 (high complexity, 37 months to judgment), the owner could have 13+ months remaining before judgment and additional 3 months before OOS. **Without judgment date, next hearing date, or docket activity, we cannot determine urgency level.** The owner may have anywhere from 3 weeks to 16+ months depending on actual case progression.\n\n## 3. ACQUISITION STRATEGY\n**DO NOT CONTACT—INCOMPLETE INTELLIGENCE.** Attempting outreach without defendant name, property address, or debt figures is operationally impossible and legally problematic. This record must be re-scraped or manually pulled from Dallas County records before any acquisition action. **Red flags:** The complete absence of data suggests either a technical scraping failure, a sealed/restricted case (unlikely for tax suits), or a placeholder docket. **Required next steps:** (1) Pull physical court file or re-query Dallas County database for TX-23-00569, (2) Obtain defendant name and property address from county tax assessor using any partial account data, (3) Run title search and valuation once property is identified. Only after obtaining debt amount ($X owed) and property value can we calculate an acceptable offer range—typically 40-60% of equity after debt satisfaction for pre-foreclosure deals.','\n',char(10)),'','pre_judgment',286730.0,226910.24999999998001,'2026-06-02','2026-05-12','2026-06-12T14:33:24.445325','2026-07-05T22:35:40.185884','2026-06-12T23:55:05.030226',1,NULL,NULL,NULL,NULL);
INSERT INTO cases VALUES(6,'TX-25-00093','298th District Court','GINSBERG, CARL','2025-01-22','CLOSED','TAX DELINQUENCY','MAJALCA, LETICIA C.','["MAJALCA, LETICIA C.", "ARIZOLA, LUIS"]','','','','LGBS (Linebarger)','ATKINS, ASHLY STEELE',NULL,NULL,'[]',2,0,0,'[]',0,0,0,'One defendant (LETICIA C. MAJALCA) was not successfully served - unexecuted citation returned 04/11/2025. LUIS ARIZOLA was served 04/23/2025.','low','Case dismissed before judgment. Only 2 defendants, standard LGBS tax suit, but service issues with primary defendant led to dismissal.','2025-10-21','non-suit/dismissal',NULL,0,NULL,NULL,NULL,NULL,'dallas','/Users/stephenlewis/Downloads/pcpeak_platform/data/pdfs/TX-25-00093/petition.pdf','[]',replace('# ACQUISITION INTELLIGENCE MEMO\n**Case TX-25-00093 | MAJALCA/ARIZOLA | Dallas County**\n\n## PROPERTY & OWNER SITUATION\nCo-owners Leticia C. Majalca and Luis Arizola face tax foreclosure in Dallas County, though financial details are incomplete in the docket (total due at filing: $0 reported, which indicates data extraction issues—typical LGBS cases average $8K-$25K in back taxes for residential properties). The case was filed January 22, 2025 by Linebarger Goggan (LGBS), the most aggressive tax collection firm in Texas. Two defendants suggest either a married couple, family co-ownership, or inherited property situation. Without property address or account number, we cannot pull county appraisal data to assess equity position, but the service problems and ultimate dismissal suggest either (1) Majalca has abandoned the property or relocated, or (2) she''s actively evading service. The case was **dismissed October 21, 2025** after Majalca could not be served despite successful service on Arizola April 23rd.\n\n## TIMELINE & URGENCY\n**ZERO IMMEDIATE URGENCY—CASE DISMISSED.** The taxing authority gave up after 9 months when they couldn''t serve the primary defendant. However, this is a **temporary reprieve only**. LGBS will re-file within 60-180 days once they obtain a better address or pursue substitute service (posting/publication) under Rule 106. The dismissal clock resets—when re-filed, expect 14-18 months to judgment based on TX-25-00492 benchmark (LOW complexity), then 90-120 days to Order of Sale. The owners have approximately **3-6 months before re-filing**, then another 16-20 months before courthouse steps auction. This dismissed status creates a unique window: the defendants may believe the problem "went away" and are vulnerable to reality-check outreach.\n\n## ACQUISITION STRATEGY\n**CONTACT IMMEDIATELY.** The dismissal creates perfect approach conditions—the owners aren''t in crisis mode but the debt hasn''t vanished. **Multi-channel blitz**: (1) Skip-trace both defendants for current addresses/phones, (2) Direct mail to last known address AND property address (if different) with "CASE DISMISSED—BUT NOT RESOLVED" messaging, (3) Door-knock the property within 10 days if occupied. Offer structure: **70-80% of appraised value minus total tax debt** (once we obtain actual numbers from Dallas CAD)—if they owe $15K and property is worth $120K, offer $85-95K cash, close in 14 days. **RED FLAGS**: Service evasion suggests either sophisticated avoidance or total disengagement; co-defendant structure may cause decision-making delays or disputes between owners. The missing financial data is critical—**DO NOT proceed without pulling account #43 from Dallas County tax records first**. If debt exceeds 40% of value, this becomes a tax-payoff deal, not an acquisition.','\n',char(10)),'Standard LGBS tax foreclosure case that was dismissed, likely due to inability to serve primary defendant MAJALCA despite successful service on co-defendant ARIZOLA.','judgment_entered',NULL,NULL,NULL,NULL,'2026-06-12T21:42:46.418752','2026-07-05T22:35:40.185232','2026-06-12T21:42:46.418752',1,NULL,NULL,NULL,NULL);
INSERT INTO cases VALUES(23,'TX-26-00989','68th District Court','GINSBERG, CARL','2026-05-19','OPEN','TAX DELINQUENCY','Amy Ortega','[{"name": "Amy Ortega", "address": "1549 Harris Ct., Dallas, TX 75223", "serviceStatus": "unserved", "serviceMethod": "private process server", "isInRemOnly": false, "notes": "Citation issued 05/20/2026, unserved as of last docket entry"}]','1549 Harris Ct., Dallas, TX 75223',NULL,'00000153766000000','LGBS (Linebarger)','JONES, STEPHEN EARL',NULL,NULL,'[]',1,0,0,'[]',0,0,0,'Citation issued but unserved as of docket review','low',NULL,NULL,'none',NULL,0,'2027-01-27',NULL,NULL,NULL,'dallas',NULL,'[]',replace('# ACQUISITION INTELLIGENCE MEMO\n**Case TX-26-00989 | Amy Ortega | 1549 Harris Ct., Dallas 75223**\n\n## PROPERTY & OWNER SITUATION\n\nDCAD account 00000153766000000 requires immediate pull to establish structure-vs-land play determination. The 75223 zip (East Dallas, Pleasant Grove area) typically shows older housing stock from 1950s-1970s with moderate depreciation curves. Without assessed values visible in case data, comparison metrics are critical: if land value exceeds 40% of total assessment, this trends toward teardown/land play given Pleasant Grove''s ongoing gentrification pressure from Lake Highlands expansion. The Harris Court address suggests residential single-family on standard 6,000-7,500 SF lots common to that grid. Amy Ortega appears as sole defendant with property address matching service address—indicating owner-occupancy or recent ownership with maintained contact information. No prior related suits in docket history signals this is either a first-time delinquency event or Ortega acquired post-2023. Payment history gap (no delinquency years listed in data) is a red flag requiring immediate DCAD portal verification—either data extraction error or very recent acceleration. If she''s a 2024-2025 purchaser who immediately went delinquent, we''re likely looking at financial distress or inheritance/divorce transfer that came with hidden liens.\n\n## FINANCIAL PICTURE\n\nCritical data gap: totalDueAtFiling shows $0 and delinquencyYears array is empty, which is impossible for a filed tax suit. This represents either a data scrape error or Linebarger filing before finalizing penalty calculations. Based on 75223 median tax bills ($3,200-$4,800 annually for SFR), a legitimate filing would require minimum 2-year delinquency. Conservative estimate: $8,000-$12,000 base taxes plus 12-24 months of penalties/interest at roughly 13% annually compounds to $10,400-$16,800 current live balance. If this includes 2024-2025 tax years with 2026 filing, penalty acceleration remains moderate—approximately $400-$800 accrued since May 2026 filing. Actual payoff today (January 2027) likely sits at $11,000-$18,000 depending on underlying assessment. DCAD shows Pleasant Grove SFRs ranging $180K-$280K market value, suggesting debt-to-value ratio between 4.5-9.5%—highly attractive margin. If property appraises above $220K, we maintain 92%+ equity cushion even at $18','\n',char(10)),NULL,'pre_judgment',NULL,NULL,NULL,NULL,'2026-07-01T23:44:55.970438','2026-07-06T01:56:19.310701','2026-07-06T01:56:19.310701',1,'individual','high','','{"account_number": "00000153766000000", "market_value": 158830, "land_value": 109480, "improvement_value": 49350, "estimated_annual_taxes": 3536.68, "year_built": 1906, "effective_year_built": 1906, "actual_age": 120, "building_class": "04", "construction_type": "FRAME", "foundation": "PIER AND BEAM", "roof_type": "", "roof_material": "", "exterior_wall": "", "living_area_sqft": 713, "total_area_sqft": 713, "bedrooms": 1, "bathrooms": "", "stories": "", "depreciation_pct": 60, "desirability": "FAIR", "air_condition": "WINDOW", "heating": "", "garage_sqft": null, "zoning": "DUPLEX DISTRICT", "lot_frontage_ft": 85, "lot_depth_ft": 92, "lot_area_sqft": 7820.0, "land_unit_price": 14.0, "legal_description": "1: FOREMANS 2: BLK G/1443 LOT 2A 3: 4: INT201500164252 DD06232015 CO-DC 5: 14