INSERT INTO cases VALUES(24,'TX-26-00990','191st District Court','GINSBERG, CARL','2026-05-19','OPEN','TAX DELINQUENCY','HECTOR LOPEZ LOPEZ','[{"name": "Hector Lopez Lopez", "address": "10130 Shayna Dr., Dallas, TX 75217", "serviceStatus": "unserved", "serviceMethod": "Private Process Server", "isInRemOnly": false, "notes": "Primary defendant"}, {"name": "Dan Leung", "address": "10130 Shayna Dr., Dallas, TX 75217", "serviceStatus": "unserved", "serviceMethod": "Private Process Server", "isInRemOnly": true, "notes": "In Rem Only defendant"}]','10130 SHAYNA DR, DALLAS, TX 75217',NULL,'00000170764000000','LGBS (Linebarger)','JONES, STEPHEN EARL',NULL,NULL,'[]',2,0,0,'["TX-13-30765, styled DALLAS COUNTY, ET AL VS. CORNELIA WEBB, filed in the 14TH DISTRICT COURT of Dallas County, Texas"]',0,0,0,'Both defendants unserved as of last docket entry','medium',NULL,NULL,'none',NULL,0,'2027-01-27',NULL,NULL,NULL,'dallas',NULL,'[{"entity": "DALLAS COUNTY", "taxAmt": 0, "penaltyInterest": 0, "total": 0}, {"entity": "PARKLAND HOSPITAL DISTRICT", "taxAmt": 0, "penaltyInterest": 0, "total": 0}, {"entity": "DALLAS COLLEGE", "taxAmt": 0, "penaltyInterest": 0, "total": 0}, {"entity": "DALLAS COUNTY SCHOOL EQUALIZATION FUND", "taxAmt": 0, "penaltyInterest": 0, "total": 0}, {"entity": "DALLAS INDEPENDENT SCHOOL DISTRICT", "taxAmt": 0, "penaltyInterest": 0, "total": 0}, {"entity": "CITY OF DALLAS", "taxAmt": 0, "penaltyInterest": 0, "total": 0}]',replace('# ACQUISITION MEMO - PC PEAK DEVELOPMENT\n\n**Property:** 10130 Shayna Dr., Dallas, TX 75217  \n**Case:** TX-26-00990 | 191st District Court | Judge Ginsberg  \n**Owner:** Hector Lopez Lopez (Individual)\n\n---\n\n## Owner Situation and Debt\n\nThe property is owned by individual Hector Lopez Lopez, who resides at the subject property address. A second party, Dan Leung, is listed as an "In Rem Only" defendant at the same address, suggesting potential co-ownership, lien interest, or tenant arrangement. Both defendants remain unserved via private process server. The case was filed May 19, 2026, by LGBS (Linebarger) on behalf of Dallas County. Tax breakdown data is incomplete in the file, indicating total debt amounts are not yet available. Given the individual ownership structure and residential address match, this appears to be an owner-occupied situation where the owner may be experiencing financial distress but has not yet been formally notified of the lawsuit.\n\n## Timeline vs. Benchmarks\n\nThe case is currently at **0 months since filing** (filed May 2026). Compared to benchmark TX-23-00042 (HIGH priority: 37 months to judgment, 89 days to OOS), this case is in the earliest stages with significant runway before judgment. Benchmark TX-25-00492 (LOW priority: 14 months to judgment) suggests faster-moving cases in this jurisdiction, but both comparables indicate we have a 12-18 month window minimum before judgment risk. With unserved defendants and no service completion, we''re likely 3-6 months from any meaningful court progression. This timeline provides excellent opportunity for pre-judgment acquisition at optimal pricing.\n\n## Acquisition Strategy\n\n**Contact Method:** Door knock primary residence FIRST (owner-occupied individual), followed by direct mail campaign if no contact established within 14 days. Use soft approach emphasizing problem-solving given the unserved status.\n\n**Offer Range:** Without complete tax data, recommend **$15,000-$25,000 initial offer** (subject to property comp analysis and final debt verification). Position as immediate cash relief before legal costs escalate. Target close within 45 days of first contact.\n\n**Next Steps:** Obtain full tax debt amount, run property comps, deploy door knock within 7 days, prepare follow-up mail sequence with 3-touch campaign over 21 days.','\n',char(10)),NULL,'pre_judgment',NULL,NULL,NULL,NULL,'2026-07-01T23:55:33.886153','2026-07-05T22:35:40.184372','2026-07-04T20:00:15.953581',1,'individual','high','',NULL);
